      "mainEntity": [
        {
          "@type": "Question",
          "name": "What causes water hammer in household pipes?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "A sudden change in water flow can create a pressure surge and a banging sound. Pipe support, valves and the installation may contribute. A plumber assesses the pattern and system before specifying the appropriate work."
          }
        },
        {
          "@type": "Question",
          "name": "Can low water pressure be a public supply issue?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes. A property-wide change may involve supply conditions as well as private plumbing. Check Water Corporation notices, particularly if neighbours are affected. A single slow outlet is a different starting point for investigation."
          }
        },
        {
          "@type": "Question",
          "name": "Can you investigate low water pressure throughout the house?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes. Report which outlets are affected, whether hot and cold differ and when the change began. We assess the private installation and explain any utility referral or repair findings."
          }
        },
        {
          "@type": "Question",
          "name": "Will a booster pump fix every low-pressure problem?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "No. The cause and supply conditions must be established first. Do not assume that installing a pump or altering a valve is appropriate or authorised for the property."
          }
        }
      ]
    }
